#include <vector>

class Solution {
public:
    int countPopcountDepth(int n, int k) {
        if (n < 1) return 0;
        std::vector<int> depth(n + 1, 0);
        depth[1] = 0;

        auto get_cnt = [](int x) {
            int c = 0;
            while (x) {
                c += (x & 1);
                x >>= 1;
            }
            return c;
        };

        int ans = 0;
        for (int i = 1; i <= n; ++i) {
            if (i > 1) {
                depth[i] = 1 + depth[get_cnt(i)];
            }
            if (depth[i] == k) ans++;
        }

        return ans;
    }
};

class Solution {
    public int countPopcountDepth(int n, int k) {
        if (n < 1) return 0;
        int[] depth = new int[n + 1];
        depth[1] = 0;

        int ans = 0;
        for (int i = 1; i <= n; i++) {
            if (i > 1) {
                depth[i] = 1 + depth[Integer.bitCount(i)];
            }
            if (depth[i] == k) ans++;
        }

        return ans;
    }
}

