var countPopcountDepth = function(n, k) {
    if (n < 1) return 0;
    const depth = new Int32Array(n + 1);
    depth[1] = 0;

    const bitCount = (x) => {
        let c = 0;
        while (x > 0) {
            c += (x & 1);
            x >>= 1;
        }
        return c;
    };

    let ans = 0;
    for (let i = 1; i <= n; i++) {
        if (i > 1) {
            depth[i] = 1 + depth[bitCount(i)];
        }
        if (depth[i] === k) ans++;
    }

    return ans;
};
